const HistoricalValuationCutoff int64 = 1790726400000 // 2026-09-30T00:00:00Z, inclusive.

// HistoricalImportCheckpoint is supplied explicitly by the importer, never by a
// report clock. SourceCheckpoint identifies the frozen source backup/import.
type HistoricalImportCheckpoint struct {
	SourceCheckpoint    string `json:"source_checkpoint"`
	EventsThrough       int64  `json:"events_through"`
	ObservationsThrough int64  `json:"observations_through"`
	At                  int64  `json:"h_ms"`
}

// CycleClosure is optional source-backed canonical cycle evidence from the
// observation/import layer. End is the actual end, not the old scheduled reset
// or the time a later poll noticed it. Uncertain bounds must include End.
// A mere utilization drop or revised deadline cannot manufacture this record.
type CycleClosure struct {
	WindowID string `json:"window_id"`
	End      int64  `json:"end_ms"`
	Earliest int64  `json:"earliest_ms"`
	Latest   int64  `json:"latest_ms"`
	Status   string `json:"status"` // closed, superseded, or uncertain
}

type WindowCompletion struct {
	CycleClosure
	ObservationID string `json:"observation_id,omitempty"`
	Source        string `json:"source"`
}

type HistoricalValuation struct {
	ID string `json:"id"`
	HistoricalImportCheckpoint
	Cutoff         int64                       `json:"cutoff_ms"`
	Timezone       string                      `json:"timezone"`
	Wording        string                      `json:"user_wording"`
	CompletionRule string                      `json:"completion_rule"`
	Windows        map[string]WindowCompletion `json:"windows"`
}

// WindowValuation is a decision, not a change to source usage. Counts live in
// APIValue, including a disjoint assumed category and the unresolved remainder.
type WindowValuation struct {
	RuleID           string           `json:"rule_id"`
	HistoricalID     string           `json:"historical_id,omitempty"`
	SourceCheckpoint string           `json:"source_checkpoint,omitempty"`
	Cutoff           int64            `json:"cutoff_ms,omitempty"`
	H                int64            `json:"h_ms,omitempty"`
	Completion       WindowCompletion `json:"completion"`
	Assume5m         bool             `json:"assume_5m"`
	Reason           string           `json:"reason"`
}

func validValueRuleID(id string) bool {
	for _, policy := range []string{legacyProfileValuePolicy, profileValuePolicy} {
		if strings.HasPrefix(id, policy+":") && len(id) == len(policy)+33 {
			return true
		}
	}
	return false
}

func (a *APIValue) setBasis() {
	switch {
	case a.Invalid > 0:
		a.Basis = "invalid_counters"
	case a.Missing > 0:
		a.Basis = "missing_price"
	case a.Tokens.WriteUnknown > 0 && a.Tokens.WriteAssumed5m > 0:
		a.Basis = "assumed_5m_and_unresolved"
	case a.Tokens.WriteUnknown > 0:
		a.Basis = "unresolved"
	case a.Tokens.WriteAssumed5m > 0:
		a.Basis = "assumed_5m"
	default:
		a.Basis = "reported_categories"
	}
}

// PinHistoricalValuation freezes the cohort once per explicit import. Repeating
// the same import is idempotent; a deliberate different checkpoint creates a new
// policy. Existing books embed their old cohort and replay independently.
func (s *Service) PinHistoricalValuation(ctx context.Context, cp HistoricalImportCheckpoint) (HistoricalValuation, error) {
	h := HistoricalValuation{HistoricalImportCheckpoint: cp, Cutoff: HistoricalValuationCutoff, Timezone: "UTC", Wording: "Whole historical windows completed after September 29, 2026, including crossing weeks", CompletionRule: "whole canonical completed window; actual early reset; inclusive [cutoff,H]; source checkpoint bounded", Windows: map[string]WindowCompletion{}}
	if strings.TrimSpace(cp.SourceCheckpoint) == "" || cp.At < h.Cutoff || cp.EventsThrough < 0 || cp.ObservationsThrough < 0 {
		return h, errors.New("explicit historical source checkpoint and H are required")
	}
	if err := s.acquireHistory(ctx); err != nil {
		return h, err
	}
	defer s.releaseHistory()
	var events, observations int64
	if err := s.db.QueryRowContext(ctx, `SELECT coalesce((SELECT value FROM analytics_state WHERE name='events'),0),coalesce((SELECT max(rowid) FROM analytics_observations),0)`).Scan(&events, &observations); err != nil {
		return h, err
	}
	if cp.EventsThrough > events || cp.ObservationsThrough > observations {
		return h, errors.New("historical checkpoint exceeds imported evidence")
	}
	accounts, err := s.Accounts(ctx)
	if err != nil {
		return h, err
	}
	for _, a := range accounts {
		_, obs, err := s.evidence(ctx, a.ID, cp.EventsThrough, cp.ObservationsThrough)
		if err != nil {
			return h, err
		}
		bounded := []Observation{}
		for _, o := range obs {
			if o.Observed <= cp.At && o.Received <= cp.At {
				bounded = append(bounded, o)
			}
		}
		for _, w := range deriveValuationWindows(a, bounded, nil, cp.At, ComparisonPriceBook{Policy: profileValuePolicy}) {
			c := completionOf(w)
			if w.Provider == "claude" && c.Status == "closed" && c.Earliest >= h.Cutoff && c.Latest <= cp.At {
				h.Windows[w.ID] = c
			}
		}
	}
	h.ID = "historical-5m-v1:" + digest(string(encode(h)))
	tx, err := s.db.BeginTx(ctx, nil)
	if err != nil {
		return h, err
	}
	defer tx.Rollback()
	if _, err = tx.ExecContext(ctx, `INSERT OR IGNORE INTO analytics_historical_valuations(id,payload) VALUES(?,?)`, h.ID, string(encode(h))); err != nil {
		return h, err
	}
	if _, err = tx.ExecContext(ctx, `INSERT INTO analytics_state(name,value) SELECT 'historical_valuation',rowid FROM analytics_historical_valuations WHERE id=? ON CONFLICT(name) DO UPDATE SET value=excluded.value`, h.ID); err != nil {
		return h, err
	}
	err = tx.Commit()
	s.wakeWorkspace()
	return h, err
}

func (s *Service) historicalValuation(ctx context.Context) (*HistoricalValuation, error) {
	var raw string
	err := s.db.QueryRowContext(ctx, `SELECT payload FROM analytics_historical_valuations WHERE rowid=(SELECT value FROM analytics_state WHERE name='historical_valuation')`).Scan(&raw)
	if errors.Is(err, sql.ErrNoRows) {
		return nil, nil
	}
	if err != nil {
		return nil, err
	}
	var h HistoricalValuation
	err = json.Unmarshal([]byte(raw), &h)
	return &h, err
}

func completionOf(w Window) WindowCompletion {
	if w.Completion != nil {
		return *w.Completion
	}
	lo, hi := w.ResetEarliest, w.ResetLatest
	if lo == 0 {
		lo = w.Reset
	}
	if hi == 0 {
		hi = w.Reset
	}
	c := WindowCompletion{CycleClosure: CycleClosure{WindowID: w.ID, End: w.Reset, Earliest: lo, Latest: hi, Status: w.Status}, Source: "retained_provider_reset"}
	if w.BoundaryRevision || w.Kind == "ledger" || strings.HasPrefix(w.Coverage, "idle quota") {
		c.Status = "uncertain"
	}
	return c
}

func windowValuation(w Window, book ComparisonPriceBook) WindowValuation {
	d := WindowValuation{RuleID: book.ID, Completion: completionOf(w), Reason: "no_historical_import"}
	if book.Policy != profileValuePolicy {
		d.Reason = "legacy_policy"
		return d
	}
	h := book.Historical
	if h == nil {
		return d
	}
	d.HistoricalID, d.SourceCheckpoint, d.Cutoff, d.H = h.ID, h.SourceCheckpoint, h.Cutoff, h.At
	switch {
	case w.Status != "closed" || d.Completion.Status != "closed":
		d.Reason = "not_canonical_closed"
	case d.Completion.Earliest < h.Cutoff && d.Completion.Latest >= h.Cutoff:
		d.Reason = "uncertain_cutoff"
	case d.Completion.Earliest < h.Cutoff:
		d.Reason = "before_cutoff"
	case d.Completion.Latest > h.At:
		d.Reason = "after_h_or_uncertain_h"
	default:
		if c, ok := h.Windows[w.ID]; !ok || c.CycleClosure != d.Completion.CycleClosure {
			d.Reason = "outside_frozen_cohort_or_revised"
		} else {
			d.Assume5m = true
			d.Reason = "whole_completed_window_assumed_5m"
		}
	}
	return d
}

func valueWindowEvent(e Event, book ComparisonPriceBook, d WindowValuation) APIValue {
	assume := d.Assume5m && book.Historical != nil && e.ID > 0 && e.ID <= book.Historical.EventsThrough && e.Recorded <= book.Historical.At && e.Completed <= book.Historical.At
	return valueEventAssumption(e, book, assume)
}

// Keep v2's derivation untouched. Only explicit source-backed closure evidence
// can distinguish an early completed cycle from a superseded reset revision.
func deriveValuationWindows(a Account, obs []Observation, events []Event, at int64, book ComparisonPriceBook) []Window {
	windows := Derive(a, obs, events, at)
	if book.Policy != profileValuePolicy {
		return windows
	}
	for i := range windows {
		w := &windows[i]
		var chosen *Observation
		conflict := false
		for j := range obs {
			o := &obs[j]
			c := o.ClosedCycle
			if c == nil || c.WindowID != w.ID || o.Account != w.Account || o.Kind != w.Kind || o.Scope != w.Scope || o.Source == "" || o.Observed > at || o.Received > at {
				continue
			}
			if chosen != nil && *chosen.ClosedCycle != *c {
				conflict = true
			}
			if chosen == nil || o.ID < chosen.ID {
				chosen = o
			}
		}
		if chosen == nil {
			continue
		}
		c := *chosen.ClosedCycle
		if conflict || c.Earliest <= w.Start || c.Earliest < w.LastObserved || c.End < c.Earliest || c.End > c.Latest || c.Latest > chosen.Observed || c.Latest > at || c.End > w.Reset {
			c.Status = "uncertain"
		}
		w.Completion = &WindowCompletion{CycleClosure: c, ObservationID: chosen.ID, Source: chosen.Source}
		if c.Status == "superseded" {
			w.Status = "superseded"
		}
		if c.Status != "closed" {
			continue
		}
		w.Status, w.AttributionEnd = "closed", c.End

		w.Tokens, w.Requests, w.Failed, w.CostNano, w.Unpriced, w.Straddling, w.ClockSkew = Tokens{}, 0, 0, 0, 0, 0, 0
		for _, e := range events {
			if !inWindow(e, *w) {
				continue
			}
			addTokens(&w.Tokens, e.Tokens)
			w.Requests++
			if e.Failed {
				w.Failed++
			}
			if e.CostNano == nil {
				w.Unpriced++
			} else {
				w.CostNano += *e.CostNano
			}
			if e.Completed >= c.End {
				w.Straddling++
			}
			if e.HeaderTime > 0 && (e.HeaderTime < e.Started-5000 || e.HeaderTime > e.Completed+5000) {
				w.ClockSkew++
			}
		}
	}
	return windows
}
